test("インスタンス自身の値の編集は自身の値を変え、公開 prop の上書きを変えない", () => {
  const edited = Node.applyRefOwnPropEdit(
    { name: "submit", ref: "primary-button", overrides: { label: "保存" } },
    PropEdit.set(["locking"], "locked"),
  );

  expect(edited).toEqual(
    Result.ok({
      name: "submit",
      ref: "primary-button",
      locking: "locked",
      overrides: { label: "保存" },
    }),
  );
});

test("インスタンス自身の値として持てない prop の編集は、その prop の名前で失敗する", () => {
  const edited = Node.applyRefOwnPropEdit(
    { name: "submit", ref: "primary-button" },
    PropEdit.set(["label"], "保存"),
  );

  expect(edited).toEqual(Result.err(["label"]));
});

test("持てない prop が 2 つ以上あれば、編集が指す順にすべての名前で失敗する", () => {
  const edited = Node.applyRefOwnPropEdit(
    { name: "submit", ref: "primary-button" },
    PropEdit.set(["label", "gap"], "md"),
  );

  expect(edited).toEqual(Result.err(["label", "gap"]));
});

test("ロックを持つ参照ノードは name・ref・locking・overrides の順で書き出される", () => {
  const written = Node.toJson({
    name: "submit",
    ref: "primary-button",
    overrides: { label: "保存" },
    locking: "locked",
  });

  expect(Object.keys(written)).toEqual(["name", "ref", "locking", "overrides"]);
});

test("参照ノード直下のロックは語彙に無い綴りでも読み込まれる", () => {
  const node = Result.unwrap(
    Node.fromJson(
      Json.create(
        { name: "submit", ref: "primary-button", locking: "frozen" },
        "node",
      ),
    ),
  );

  expect(node).toEqual({
    name: "submit",
    ref: "primary-button",
    locking: "frozen",
  });
});

test("部品インスタンスのスキーマが宣言する prop は、参照ノードがインスタンス自身の値として持てる prop と完全に一致する", () => {
  expectTypeOf<
    keyof typeof RefOwnPropDefinitions
  >().toEqualTypeOf<RefOwnPropName>();
});

test("ロックと書いたインスタンスはロックされている", () => {
  const document = setupInstanceDocument({ locking: "locked" });

  expect(DesignDocument.isLocked(document, "login")).toBe(true);
});

test("公開 prop の上書きにロックと書いたインスタンスはロックされていない", () => {
  const document = setupInstanceDocument({ overrides: { locking: "locked" } });

  expect(DesignDocument.isLocked(document, "login")).toBe(false);
});

test("インスタンス自身の値として持てない prop は編集できない", () => {
  const edited = DesignDocument.applyRefOwnPropEdit(
    setupDocument(),
    "home-action",
    PropEdit.set(["label"], "送信"),
  );

  expect(edited).toEqual(
    Result.err({
      kind: "ref-own-prop-not-allowed",
      name: "home-action",
      props: ["label"],
    }),
  );
});

test("ロックしたノードを部品化すると、参照ノードがロックされ部品の根にはロックが残らない", () => {
  const document = setupBoxDocument({ locking: "locked", gap: "md" });

  const result = Result.unwrap(
    DesignDocument.createComponent(document, "box-1", "card"),
  );

  expect([result.artboards[0].children, result.components.card]).toEqual([
    [{ name: "box-1", ref: "card", locking: "locked" }],
    { type: "Box", props: { gap: "md" } },
  ]);
});

test("unlocked と明示したノードを部品化すると、その値を参照ノードへ移し部品の根に残さない", () => {
  const document = setupBoxDocument({ locking: "unlocked" });

  const result = Result.unwrap(
    DesignDocument.createComponent(document, "box-1", "card"),
  );

  expect([result.artboards[0].children, result.components.card]).toEqual([
    [{ name: "box-1", ref: "card", locking: "unlocked" }],
    { type: "Box" },
  ]);
});

test("ロックしたインスタンスを解除すると、展開した根がロックされている", () => {
  const document = setupInstanceDocument(
    { name: "save-button", ref: "primary-button", locking: "locked" },
    components,
  );

  const result = Result.unwrap(DesignDocument.detach(document, "save-button"));

  expect(DesignDocument.isLocked(result, "save-button")).toBe(true);
});

test("部品の根がロックしていても、ロックを書いていないインスタンスは解除後にロックされていない", () => {
  const document = setupInstanceDocument(
    { name: "save-button", ref: "frozen-button" },
    {
      "frozen-button": {
        type: "Box",
        props: { locking: "locked" },
        children: [],
      },
    },
  );

  const result = Result.unwrap(DesignDocument.detach(document, "save-button"));

  expect(DesignDocument.isLocked(result, "save-button")).toBe(false);
});

test("インスタンス自身のロックが書かれていなければ、展開した根から部品の根のロックは消える", () => {
  const components: ComponentSet = {
    card: { type: "Box", props: { background: "primary", locking: "locked" } },
  };
  const instance: RefNode = { name: "panel", ref: "card" };

  const expanded = Result.unwrap(ExpandedNode.fromNode(instance, components));

  expect(expanded.props).toEqual({ background: "primary" });
});

test("インスタンスに語彙に無い綴りのロックを書くと enum-violation エラーになる", () => {
  const errors = DesignDocument.collectErrors(setupInstanceDocument("frozen"));

  expect(errors).toEqual([
    expect.objectContaining({
      kind: "enum-violation",
      nodeName: "login",
      prop: "locking",
    }),
  ]);
});

test("artboard 直下のロックしたインスタンスの中を押すと、インスタンスもその中身も選ばない", () => {
  const document = DesignDocument.create({
    components: {
      badge: {
        type: "Box",
        children: [{ name: "badge-label", type: "Text" }],
      },
    },
    artboards: [
      {
        name: "home",
        width: 360,
        height: 240,
        children: [{ name: "home-badge", ref: "badge", locking: "locked" }],
      },
    ],
  });

  const name = DocumentSelection.nodeNameAt(
    DocumentSelection.fromNames(document, []),
    ["badge-label", "home-badge", "home"],
    SelectionDigs.Deepest,
  );

  expect(name).toEqual(Option.none);
});

test("公開 prop の上書きに書いたロックは、ロックの欄の値にならない", () => {
  const selection = setupInstanceSelection({
    name: "action",
    ref: "primary-button",
    overrides: { locking: "locked" },
  });

  expect(
    controlNamed(instanceOf(selection).refOwnProps, "locking").value,
  ).toEqual(Option.none);
});

test("ロックしたインスタンスの中身をクリックすると artboard が選ばれる", () => {
  const state = EditorState.selectAt(
    EditorState.clearSelection(stateWithLockedInstance()),
    InstanceNames,
    SelectionDigs.NoDeeper,
  );

  expect(EditorState.singleName(state)).toEqual(Option.some("home"));
});

test("範囲に入ったロック中のインスタンスは選ばれず、隣のノードだけが選ばれる", () => {
  const state = EditorState.selectInRange(
    EditorState.clearSelection(stateWithLockedInstance()),
    ["home-login", "sibling-panel"],
  );

  expect(EditorState.singleName(state)).toEqual(Option.some("sibling-panel"));
});

test("ロックしたインスタンスもツリーから名前で選べる", () => {
  const state = EditorState.select(
    EditorState.clearSelection(stateWithLockedInstance()),
    "home-login",
  );

  expect(EditorState.singleName(state)).toEqual(Option.some("home-login"));
});

test("ロックを外したインスタンスはキャンバスのクリックで選べるようになる", () => {
  const unlocked = Option.unwrap(
    EditorState.applyRefOwnPropEdit(
      stateWithLockedInstance(),
      PropEdit.set(["locking"], "unlocked"),
      EditContinuities.Separate,
    ),
  );

  const state = EditorState.selectAt(
    EditorState.clearSelection(unlocked),
    InstanceNames,
    SelectionDigs.NoDeeper,
  );

  expect(EditorState.singleName(state)).toEqual(Option.some("home-login"));
});

test("インスタンスのロックは Undo 1 回で書く前へ戻る", () => {
  const undone = Option.unwrap(EditorState.undo(stateWithLockedInstance()));

  expect(
    DesignDocument.isLocked(EditorState.document(undone), "home-login"),
  ).toBe(false);
});

test("ロックしたあとに持てない prop の編集を送ってから元に戻すと、ロックが外れる", async () => {
  /*
   * 持てない prop の編集が履歴に段を積むと、1 回の元に戻すはその空の段を戻すだけで
   * ロックが残って落ちる。
   */
  const user = userEvent.setup();
  render(<InstanceLockHarness />);

  await user.click(screen.getByRole("button", { name: "home-card を選ぶ" }));
  await user.click(screen.getByRole("button", { name: "ロックする" }));
  await user.click(
    screen.getByRole("button", { name: "持てない prop を書く" }),
  );
  await user.click(screen.getByRole("button", { name: "元に戻す" }));

  expect(screen.getByTestId("card-locking").textContent).toBe("unlocked");
});

test("ロックの行で locked を選ぶと、インスタンス自身の値の編集が届く", async () => {
  const editRefOwnProp = vi.fn();
  renderSelected("home-login", {
    goToSource: vi.fn(),
    selectAllInstances: vi.fn(),
    detach: vi.fn(),
    editRefOwnProp,
  });

  await userEvent.click(segmentOf("Locking", "locked"));

  expect(editRefOwnProp.mock.calls[0]?.[0]).toEqual(
    PropEdit.set(["locking"], "locked"),
  );
});

test("公開 prop の件数にはインスタンス自身のロックの行を数えない", () => {
  /* `primary-button` の公開 prop は `label` の 1 件。ロックの行まで数えると 2 になって落ちる。 */
  renderSelected("home-login");

  expect(screen.getByText("1")).toBeDefined();
});

test("インスペクタでインスタンスをロックすると、キャンバスで押してもインスタンスではなく artboard が選ばれる", async () => {
  await renderOpenedDocument(setupInstanceDocument());
  await selectInTree("home-login");
  await userEvent.click(segmentOf("Locking", "locked"));
  await selectInTree("home-panel");

  await userEvent.click(renderedElement(canvasPane(), "home-login"));

  expect(within(rightPaneHeading()).getByText("home")).toBeDefined();
});

test("ツリーで選んだロック中のインスタンスは、インスペクタでロックを外すとキャンバスで選べる", async () => {
  await renderOpenedDocument(setupInstanceDocument("locked"));
  await selectInTree("home-login");
  await userEvent.click(segmentOf("Locking", "unlocked"));
  await selectInTree("home-panel");

  await userEvent.click(renderedElement(canvasPane(), "home-login"));

  expect(currentRowNames(tree())).toEqual(["home-login"]);
});

